:root {
  --bg: #1b1f3b;
  --card: #2a2f5a;
  --ink: #f4f1de;
  --accent: #f2a65a;
  --teal: #4ecdc4;
  --border: #0d0f1f;
  --radius: 0;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background-color: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255,255,255,0.035) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(255,255,255,0.035) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(255,255,255,0.035) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(255,255,255,0.035) 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0;
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--border);
  padding: 28px 24px 24px;
  box-shadow: 8px 8px 0 var(--border), 0 0 0 4px var(--teal) inset;
  image-rendering: pixelated;
}

.card-header { margin-bottom: 20px; }

h1 {
  margin: 0 0 4px;
  font-size: 1.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--teal);
  text-shadow: 2px 2px 0 var(--border);
}

.subtitle {
  margin: 0;
  font-size: 0.95rem;
  color: var(--ink);
  opacity: 0.75;
}

.field { margin-bottom: 18px; }

label, legend {
  display: block;
  margin-bottom: 6px;
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: var(--accent);
}

input[type="number"] {
  width: 100%;
  padding: 12px 14px;
  font-size: 1.1rem;
  font-family: inherit;
  color: var(--ink);
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: var(--radius);
  outline: none;
}

input[type="number"]:focus-visible {
  border-color: var(--teal);
  box-shadow: 0 0 0 3px var(--teal);
}

input[type="number"]::placeholder { color: rgba(244,241,222,0.4); }

.tip-group {
  margin: 0 0 18px;
  padding: 0;
  border: 0;
}

.tip-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.tip-btn {
  padding: 12px 4px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  color: var(--ink);
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: var(--radius);
  cursor: pointer;
  transition: transform 0.05s ease, background-color 0.15s ease, color 0.15s ease;
}

.tip-btn:hover { background: var(--teal); color: var(--border); }

.tip-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.tip-btn:active { transform: translate(2px, 2px); }

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--border);
  box-shadow: 4px 4px 0 var(--border);
  transform: translate(-2px, -2px);
}

.results {
  margin-top: 8px;
  padding: 16px;
  background: var(--bg);
  border: 3px solid var(--border);
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 6px 0;
}

.result-row + .result-row {
  border-top: 2px dashed rgba(244,241,222,0.2);
  margin-top: 6px;
  padding-top: 12px;
}

.result-label {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  opacity: 0.8;
}

.result-value {
  font-size: 1.25rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.highlight .result-value { color: var(--teal); font-size: 1.5rem; }

.hint {
  min-height: 1.5em;
  margin: 14px 0 0;
  font-size: 0.85rem;
  color: var(--accent);
}

@media (max-width: 400px) {
  .card { padding: 22px 16px 18px; }
  h1 { font-size: 1.5rem; }
  .tip-btn { font-size: 0.95rem; padding: 10px 2px; }
  .result-value { font-size: 1.1rem; }
  .highlight .result-value { font-size: 1.3rem; }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll('.tip-btn'));
  var tipTotalEl = document.getElementById('tip-total');
  var perPersonEl = document.getElementById('total-per-person');
  var hintEl = document.getElementById('hint');

  var tipPercent = 0;

  function formatMoney(value) {
    return '$' + value.toFixed(2);
  }

  function setActiveButton(percent) {
    tipButtons.forEach(function (btn) {
      var active = Number(btn.getAttribute('data-tip')) === percent;
      btn.setAttribute('aria-pressed', active ? 'true' : 'false');
    });
  }

  function calculate() {
    var bill = parseFloat(billInput.value);
    var people = parseInt(peopleInput.value, 10);
    var messages = [];

    if (isNaN(bill) || bill < 0) {
      bill = 0;
      if (billInput.value !== '') messages.push('Enter a valid bill amount.');
    }

    if (isNaN(people) || people < 1) {
      people = 1;
      if (peopleInput.value !== '') messages.push('At least 1 person required.');
    }

    var tipTotal = bill * (tipPercent / 100);
    var grandTotal = bill + tipTotal;
    var perPerson = grandTotal / people;

    tipTotalEl.textContent = formatMoney(tipTotal);
    perPersonEl.textContent = formatMoney(perPerson);
    hintEl.textContent = messages.join(' ');
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      tipPercent = Number(btn.getAttribute('data-tip'));
      setActiveButton(tipPercent);
      calculate();
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  // Keyboard support for tip buttons via arrow keys within the group
  tipButtons.forEach(function (btn, index) {
    btn.addEventListener('keydown', function (event) {
      var next = null;
      if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {
        next = tipButtons[(index + 1) % tipButtons.length];
      } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {
        next = tipButtons[(index - 1 + tipButtons.length) % tipButtons.length];
      }
      if (next) {
        event.preventDefault();
        next.focus();
      }
    });
  });

  calculate();
})();
